from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    for r, row in enumerate(grid):
        # Replace the trailing background section after the last stripe cell.
        last = max((c for c, v in enumerate(row) if v != background), default=-1)
        if 0 <= last < len(row) - 1:
            for c in range(last + 1, len(row)):
                if row[c] == background:
                    out[r][c] = 1

    return out
